-- itens comprados por fornecedor (detalha os lançamentos de gastos_fornecedor, categoria Insumos secos)
CREATE TABLE IF NOT EXISTS gastos_itens (
    id         serial PRIMARY KEY,
    fornecedor text NOT NULL,
    mes        date NOT NULL,
    categoria  text NOT NULL DEFAULT 'Insumos secos',
    item       text NOT NULL,
    grupo      text,
    quantidade numeric(12,3),
    unidade    text,
    preco_unit numeric(12,4),
    valor      numeric(12,2) NOT NULL,
    origem     text NOT NULL DEFAULT 'estimado' CHECK (origem IN ('estimado','nota','pago')),
    doc        text,
    detalhe    text,
    criado_em  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS gastos_itens_mes_idx ON gastos_itens (mes, fornecedor);
UPDATE gastos_fornecedor SET valor = 1892.02, obs = '03/06 (sachês e 1 caixa de grill), 15/06 (7 baconnaise + 5 grill) e 30/06 (4 caixas de grill, sachês); prazo de 14 dias liberado em 30/06'
 WHERE fornecedor = 'Garra' AND mes = '2026-06-01' AND valor = 1091.02;
ALTER TABLE gastos_itens ADD COLUMN IF NOT EXISTS detalhe text;
DELETE FROM gastos_itens WHERE categoria = 'Insumos secos' AND doc IS NOT NULL;
